package com.ecommerce.dao;

import com.ecommerce.DBConnection;
import com.ecommerce.PasswordUtil;
import com.ecommerce.User;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.sql.Types;

public class CustomerDAO {

    // Saves a customer and gets the ID generated by MySQL.
    public boolean registerCustomer(User user) throws SQLException {

        String sql = "INSERT INTO customers " + "(name, username, email, password_hash, phone_number) " + "VALUES (?, ?, ?, ?, ?)";

        String passwordHash = PasswordUtil.hashPassword(user.getPassword());

        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(
                     sql, Statement.RETURN_GENERATED_KEYS)) {

            ps.setString(1, user.getFullName());
            ps.setString(2, user.getUsername());
            setOptionalValue(ps, 3, user.getEmail());
            ps.setString(4, passwordHash);
            setOptionalValue(ps, 5, user.getPhoneNumber());

            if (ps.executeUpdate() == 1) {
                try (ResultSet rs = ps.getGeneratedKeys()) {
                    if (rs.next()) {
                        user.setUserId(rs.getInt(1));
                        user.setPassword(passwordHash);
                        return true;
                    }
                }
            }

            return false;
        }
    }

    // Finds a customer using username, email, or phone number.
    public User findByIdentifier(String identifier) throws SQLException {

        String sql = "SELECT customer_id, name, username, password_hash, "
                + "email, phone_number FROM customers "
                + "WHERE username = ? OR email = ? OR phone_number = ?";

        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sql)) {

            ps.setString(1, identifier);
            ps.setString(2, identifier);
            ps.setString(3, identifier);

            try (ResultSet rs = ps.executeQuery()) {

                if (rs.next()) {
                    return new User(rs.getInt("customer_id"), rs.getString("name"),
                            rs.getString("username"), rs.getString("password_hash"),
                            rs.getString("email"),
                            rs.getString("phone_number")
                    );
                }}}
        return null;
    }
    // Saves optional email and phone values as SQL NULL when empty.
    private void setOptionalValue(
            PreparedStatement ps, int index, String value)
            throws SQLException {
        if (value == null || value.trim().isEmpty()) {
            ps.setNull(index, Types.VARCHAR);
        } else {
            ps.setString(index, value.trim());
        }
    }

    // Check if username already exists in MySQL (case-insensitive)
    public boolean isUsernameTaken(String username) throws SQLException {
        if (username == null || username.trim().isEmpty()) {
            return false;
        }
        String sql = "SELECT 1 FROM customers WHERE LOWER(username) = LOWER(?)";
        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sql)) {
            ps.setString(1, username.trim());
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next();
            }
        }
    }

    // Check if email already exists in MySQL (case-insensitive)
    public boolean isEmailTaken(String email) throws SQLException {
        if (email == null || email.trim().isEmpty()) {
            return false;
        }
        String sql = "SELECT 1 FROM customers WHERE LOWER(email) = LOWER(?)";
        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sql)) {
            ps.setString(1, email.trim());
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next();
            }
        }
    }

    // Check if phone number already exists in MySQL
    public boolean isPhoneTaken(String phone) throws SQLException {
        if (phone == null || phone.trim().isEmpty()) {
            return false;
        }
        String sql = "SELECT 1 FROM customers WHERE phone_number = ?";
        try (Connection con = DBConnection.getConnection();
             PreparedStatement ps = con.prepareStatement(sql)) {
            ps.setString(1, phone.trim());
            try (ResultSet rs = ps.executeQuery()) {
                return rs.next();
            }
        }
    }
}